<?php
require_once __DIR__.'/../../config/conexion.php';require_once __DIR__.'/../Models/PlanillaModel.php';
class PlanillaController {private function m(){global $conexion;return new PlanillaModel($conexion);}public function index():void{autorizar('planilla.calcular');$d=$this->m()->datos();extract($d);require __DIR__.'/../Views/layouts/header.php';require __DIR__.'/../Views/layouts/navbar.php';require __DIR__.'/../Views/planilla/index.php';require __DIR__.'/../Views/layouts/footer.php';}public function guardarVinculo():void{autorizar('planilla.calcular');validarCsrf();try{$this->m()->vinculo($_POST);mensaje('success','Vínculo laboral registrado.');}catch(Throwable $e){mensaje('error','No se pudo registrar el vínculo.');}header('Location:index.php?url=planilla');exit;}public function guardarPeriodo():void{autorizar('planilla.calcular');validarCsrf();try{$this->m()->periodo($_POST);mensaje('success','Periodo de pago creado.');}catch(Throwable $e){mensaje('error','No se pudo crear el periodo.');}header('Location:index.php?url=planilla');exit;}public function calcular():void{autorizar('planilla.calcular');validarCsrf();try{$n=$this->m()->calcular((int)$_POST['id_periodo_pago']);mensaje('success',"Planilla calculada: $n registro(s).");}catch(Throwable $e){mensaje('error','No se pudo calcular la planilla.');}header('Location:index.php?url=planilla');exit;}public function guardarRegla():void{autorizar('planilla.calcular');validarCsrf();try{$this->m()->regla($_POST);mensaje('success','Regla de descuento guardada.');}catch(Throwable $e){mensaje('error','No se pudo guardar la regla.');}header('Location:index.php?url=planilla');exit;}}
